"""Small test-automation harness: runs API-style checks against a service and reports failures."""
import json

def check_response(resp: dict, expected_status: int, required_keys=()):
    errors = []
    if resp.get("status") != expected_status:
        errors.append(f"status {resp.get('status')} != {expected_status}")
    body = resp.get("body", {})
    for k in required_keys:
        if k not in body:
            errors.append(f"missing key: {k}")
    return errors

def run_suite(cases):
    report = {"passed": 0, "failed": []}
    for name, resp, exp, keys in cases:
        errs = check_response(resp, exp, keys)
        if errs:
            report["failed"].append({"test": name, "errors": errs})
        else:
            report["passed"] += 1
    return report

if __name__ == "__main__":
    cases = [
        ("get_order", {"status": 200, "body": {"id": 1, "total": 9.5}}, 200, ("id", "total")),
        ("create_order", {"status": 500, "body": {}}, 201, ("id",)),
    ]
    print(json.dumps(run_suite(cases), indent=2))
EOF
cat > test_checkout.py <<'EOF'
