def test_ok():
    assert check_response({"status": 200, "body": {"id": 1}}, 200, ("id",)) == []

def test_missing_key():
    assert check_response({"status": 200, "body": {}}, 200, ("id",)) == ["missing key: id"]

def test_suite_counts():
    r = run_suite([("a", {"status": 200, "body": {}}, 200, ())])
    assert r["passed"] == 1 and r["failed"] == []
EOF
